<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { api, post, remove, message, date, clipboard } from '../api'
import { useAuth } from '../auth'
import { useList } from '../useList'
import LoadError from '../components/LoadError.vue'
const auth=useAuth(),tokens=useList('/tokens'),users=useList('/users',false),gateway=ref<any>({}),error=ref(''),open=ref(false),saving=ref(false),formError=ref(''),issued=ref(''),resultOpen=ref(false)
const form=reactive({user_id:'',client_name:'',expires_at:'',never_expires:false})
const template=computed(()=>typeof gateway.value.template==='string'?gateway.value.template:JSON.stringify(gateway.value.template||{},null,2))
const personal=computed(()=>template.value.replace('<TOKEN>',issued.value))
const names=computed(()=>Object.fromEntries(users.items.value.map(x=>[x.id,x.username])))
async function load(){error.value='';try{gateway.value=await api('/gateway')}catch(e){error.value=message(e)}}
async function copy(value:string){try{await clipboard(value);ElMessage.success('已复制')}catch(e){ElMessage.error(message(e))}}
function create(){Object.assign(form,{user_id:auth.personal?auth.user?.id||'':'',client_name:'',never_expires:false,expires_at:new Date(Date.now()+30*86400000).toISOString()});formError.value='';open.value=true}
async function save(){saving.value=true;formError.value='';try{if((!auth.personal&&!form.user_id)||!form.client_name.trim()||(!form.never_expires&&!form.expires_at))throw new Error('请填写用户、客户端名称和有效期');const data=await post('/tokens',{...form,expires_at:form.never_expires?undefined:new Date(form.expires_at).toISOString()});issued.value=data.token;open.value=false;resultOpen.value=true;await tokens.load()}catch(e){formError.value=message(e)}finally{saving.value=false}}
async function revoke(row:any){try{await ElMessageBox.confirm(`撤销「${row.client_name}」的 Token？该客户端将无法继续调用。`,'撤销 Token',{type:'warning'});await remove(`/tokens/${row.id}`);await tokens.load();ElMessage.success('Token 已撤销')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e))}}
onMounted(()=>{load();if(auth.admin&&!auth.personal)users.load()})
</script>
<template><LoadError :error="error" @retry="load"/><div class="gateway-grid"><section class="gateway-card"><span class="eyebrow">STREAMABLE HTTP</span><h2>统一接入地址</h2><p v-if="auth.personal">为每个本机客户端签发独立 Token，默认可使用全部 MCP 和工具。</p><p v-else>为每个用户和客户端签发独立 Token，角色决定可用的 MCP 服务，<br>安全策略按客户端来源 IP 限制连接。</p><div class="endpoint"><code>{{gateway.url||'加载中…'}}</code><el-button text :disabled="!gateway.url" @click="copy(gateway.url)">复制</el-button></div><small>{{auth.personal?'个人版免登录，客户端接入仍需 Token。':'网关 Token 与 Web 登录互相独立。'}}</small></section><section class="panel code-panel"><div class="panel-toolbar"><h2>接入配置模板</h2><el-button text @click="copy(template)">复制模板</el-button></div><pre>{{template}}</pre><p class="muted">把 &lt;TOKEN&gt; 替换为管理员交付的专属 Token。</p></section></div><section class="panel"><div class="panel-toolbar"><div><h2>{{auth.admin?'访问 Token':'我的访问 Token'}}</h2><p>明文仅在签发时显示一次，遗失后请撤销并重新签发。</p></div><div class="toolbar-actions"><el-button @click="tokens.load()">刷新</el-button><el-button v-if="auth.admin" type="primary" @click="create">签发 Token</el-button></div></div><LoadError :error="tokens.error.value||users.error.value" @retry="tokens.load();auth.admin&&!auth.personal&&users.load()"/><el-table :data="tokens.items.value" v-loading="tokens.loading.value"><el-table-column prop="client_name" label="客户端" min-width="160"/><el-table-column v-if="!auth.personal" label="所属用户" min-width="160" show-overflow-tooltip><template #default="{row}">{{names[row.user_id]||row.user_id}}</template></el-table-column><el-table-column label="有效期至" min-width="190"><template #default="{row}">{{row.never_expires?'永久有效':date(row.expires_at)}}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{row}"><el-tag :type="row.revoked?'info':(row.never_expires||new Date(row.expires_at).getTime()>Date.now())?'success':'warning'" round>{{row.revoked?'已撤销':(row.never_expires||new Date(row.expires_at).getTime()>Date.now())?'有效':'已到期'}}</el-tag></template></el-table-column><el-table-column v-if="auth.admin" label="操作" width="100"><template #default="{row}"><el-button text type="danger" :disabled="row.revoked" @click="revoke(row)">撤销</el-button></template></el-table-column><template #empty><el-empty description="暂无访问 Token"/></template></el-table></section><el-dialog v-model="open" title="签发访问 Token" width="480px"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top"><el-form-item v-if="!auth.personal" label="所属用户" required><el-select v-model="form.user_id" filterable placeholder="选择已启用用户"><el-option v-for="u in users.items.value.filter(x=>x.enabled)" :key="u.id" :label="u.username" :value="u.id"/></el-select></el-form-item><el-form-item label="客户端名称" required><el-input v-model="form.client_name" placeholder="例如 张三的 Claude Code"/></el-form-item><el-form-item label="有效期"><el-radio-group v-model="form.never_expires"><el-radio-button :value="false">设置到期时间</el-radio-button><el-radio-button :value="true">永久有效</el-radio-button></el-radio-group></el-form-item><el-form-item v-if="!form.never_expires" label="到期时间" required><el-date-picker v-model="form.expires_at" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" placeholder="选择到期时间"/></el-form-item></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">签发 Token</el-button></template></el-dialog><el-dialog v-model="resultOpen" title="Token 已签发 · 仅显示一次" width="620px" :close-on-click-modal="false" @closed="issued=''"><el-alert title="请现在复制并通过安全渠道交付给对应用户。关闭后无法找回。" type="warning" :closable="false"/><pre class="secret-output">{{issued}}</pre><el-button @click="copy(issued)">复制 Token</el-button><el-divider/><h3>专属接入配置</h3><pre class="secret-output">{{personal}}</pre><template #footer><el-button @click="copy(personal)">复制专属配置</el-button><el-button type="primary" @click="resultOpen=false">已安全保存，关闭</el-button></template></el-dialog></template>
